shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/src/acl.c
+++ b/src/acl.c
@@ -2377,6 +2377,8 @@
         listRewind(server.clients, &li);
         while ((ln = listNext(&li)) != NULL) {
             client *c = listNodeValue(ln);
+            /* Clients without a user, such as the primary, bypass ACLs. */
+            if (c->user == NULL) continue;
             user *original = c->user;
             list *channels = NULL;
             user *new_user = ACLGetUserByName(c->user->name, sdslen(c->user->name));
PATCH
if [ $? -eq 0 ]; then
    make -j4 > /tmp/valkey-acl-build.log 2>&1 && ./runtest --single unit/acl --single unit/acl-v2 > /tmp/valkey-acl-tests.log 2>&1
    result=$?
    tail -15 /tmp/valkey-acl-build.log
    tail -65 /tmp/valkey-acl-tests.log
    exit $result
fi

